namespace Contracts.Infrastructure.Operations;

using System.Data;
using System.Security.Cryptography;
using Contracts.Application.Finance;
using Contracts.Application.MasterData;
using Contracts.Application.Operations;
using Microsoft.Data.Sqlite;
using Microsoft.EntityFrameworkCore.Storage;

public sealed class OperationsStore(IDbContextFactory<ContractsDbContext> factory,DocumentStorageOptions storage):IOperationsStore
{
    public async Task<OperationsReferenceData> ReferencesAsync(CancellationToken ct){await using ContractsDbContext db=await factory.CreateDbContextAsync(ct);List<OperationContractOption> contracts=await db.Contracts.AsNoTracking().Where(x=>!x.IsDeleted).OrderBy(x=>x.NormalizedContractNo).Select(x=>new OperationContractOption(x.Id,x.ContractNo,x.Title)).ToListAsync(ct);return new(contracts,await Refs<GuaranteeType>(db,ct),await Refs<GuaranteeStatus>(db,ct),await Refs<InvoiceType>(db,ct),await Refs<PaymentStatus>(db,ct),await Refs<DocumentType>(db,ct),await Refs<Bank>(db,ct));}

    public async Task<IReadOnlyList<AmendmentDto>> AmendmentsAsync(long? contractId,CancellationToken ct){await using ContractsDbContext db=await factory.CreateDbContextAsync(ct);List<AmendmentDto> rows=await AmendmentQuery(db,contractId).ToListAsync(ct);return rows.OrderByDescending(x=>x.Date).ThenByDescending(x=>x.Id).ToList();}
    public async Task<AmendmentDto> CreateAmendmentAsync(AmendmentInput x,AuditStamp stamp,CancellationToken ct){await using ContractsDbContext db=await factory.CreateDbContextAsync(ct);await using IDbContextTransaction tx=await db.Database.BeginTransactionAsync(IsolationLevel.Serializable,ct);Contract c=await db.Contracts.Include(z=>z.Amendments).SingleOrDefaultAsync(z=>z.Id==x.ContractId&&!z.IsDeleted,ct)??throw new KeyNotFoundException("Contract was not found.");ContractAmendment a=c.AddAmendment(x.Number,x.Date,x.AmountChangeRial,x.TimeExtensionDays,x.Subject,SafeOptionalRelative(x.AttachmentPath),x.Description,stamp);db.ContractAmendments.Add(a);await Save(db,ct);await tx.CommitAsync(ct);return await AmendmentById(a.Id,ct);}
    public async Task<AmendmentDto> UpdateAmendmentAsync(AmendmentUpdate x,AuditStamp stamp,CancellationToken ct){await using ContractsDbContext db=await factory.CreateDbContextAsync(ct);await using IDbContextTransaction tx=await db.Database.BeginTransactionAsync(IsolationLevel.Serializable,ct);ContractAmendment a=await db.ContractAmendments.SingleOrDefaultAsync(z=>z.Id==x.Id&&!z.IsDeleted,ct)??throw new KeyNotFoundException("Amendment was not found.");if(a.ContractId!=x.Values.ContractId)throw new ArgumentException("Amendment contract cannot change.");Contract c=await db.Contracts.SingleAsync(z=>z.Id==a.ContractId,ct);long others=await db.ContractAmendments.Where(z=>z.ContractId==c.Id&&!z.IsDeleted&&z.Id!=a.Id).SumAsync(z=>(long?)z.AmountChangeRial,ct)??0;db.Entry(a).Property(z=>z.ConcurrencyVersion).OriginalValue=x.ConcurrencyVersion;a.Update(x.Values.Number,x.Values.Date,x.Values.AmountChangeRial,x.Values.TimeExtensionDays,x.Values.Subject,SafeOptionalRelative(x.Values.AttachmentPath),x.Values.Description,c.BaseAmountRial,others,stamp);await Save(db,ct);await tx.CommitAsync(ct);return await AmendmentById(a.Id,ct);}
    public async Task DeleteAmendmentAsync(long id,long version,AuditStamp stamp,CancellationToken ct){await using ContractsDbContext db=await factory.CreateDbContextAsync(ct);await using IDbContextTransaction tx=await db.Database.BeginTransactionAsync(IsolationLevel.Serializable,ct);ContractAmendment a=await db.ContractAmendments.SingleOrDefaultAsync(z=>z.Id==id&&!z.IsDeleted,ct)??throw new KeyNotFoundException();Contract c=await db.Contracts.SingleAsync(z=>z.Id==a.ContractId,ct);long remaining=await db.ContractAmendments.Where(z=>z.ContractId==c.Id&&!z.IsDeleted&&z.Id!=id).SumAsync(z=>(long?)z.AmountChangeRial,ct)??0;if(checked(c.BaseAmountRial+remaining)<0)throw new InvalidOperationException("Deleting this amendment would make final amount negative.");db.Entry(a).Property(z=>z.ConcurrencyVersion).OriginalValue=version;a.SoftDelete(stamp);await Save(db,ct);await tx.CommitAsync(ct);}

    public async Task<IReadOnlyList<GuaranteeDto>> GuaranteesAsync(long? contractId,DateOnly today,CancellationToken ct){await using ContractsDbContext db=await factory.CreateDbContextAsync(ct);List<GuaranteeProjection> rows=await GuaranteeQuery(db,contractId).OrderBy(x=>x.Expiry).ThenBy(x=>x.Id).ToListAsync(ct);return rows.Select(x=>GuaranteeDto(x,today)).ToList();}
    public async Task<GuaranteeDto> CreateGuaranteeAsync(GuaranteeInput x,AuditStamp stamp,DateOnly today,CancellationToken ct){GuaranteeLifecyclePolicy.ValidateTransition(1,x.StatusId,x.ExpiryDate,today);await using ContractsDbContext db=await factory.CreateDbContextAsync(ct);await EnsureContract(db,x.ContractId,ct);Guarantee g=new(x.ContractId,x.Number,x.TypeId,x.StatusId,x.AmountRial,x.BankId,x.IssueDate,x.ExpiryDate,x.Description,stamp);db.Guarantees.Add(g);await Save(db,ct);return await GuaranteeById(g.Id,today,ct);}
    public async Task<GuaranteeDto> UpdateGuaranteeAsync(GuaranteeUpdate x,AuditStamp stamp,DateOnly today,CancellationToken ct){await using ContractsDbContext db=await factory.CreateDbContextAsync(ct);Guarantee g=await db.Guarantees.SingleOrDefaultAsync(z=>z.Id==x.Id&&!z.IsDeleted,ct)??throw new KeyNotFoundException();if(g.ContractId!=x.Values.ContractId)throw new ArgumentException("Guarantee contract cannot change.");db.Entry(g).Property(z=>z.ConcurrencyVersion).OriginalValue=x.ConcurrencyVersion;GuaranteeInput v=x.Values;g.Update(v.Number,v.TypeId,v.StatusId,v.AmountRial,v.BankId,v.IssueDate,v.ExpiryDate,v.Description,today,stamp);await Save(db,ct);return await GuaranteeById(g.Id,today,ct);}
    public async Task DeleteGuaranteeAsync(long id,long version,AuditStamp stamp,CancellationToken ct){await using ContractsDbContext db=await factory.CreateDbContextAsync(ct);Guarantee g=await db.Guarantees.SingleOrDefaultAsync(z=>z.Id==id&&!z.IsDeleted,ct)??throw new KeyNotFoundException();if(await db.Alerts.AnyAsync(z=>z.GuaranteeId==id&&!z.IsDeleted,ct))throw new MasterDataDependencyException("Guarantee has an alert and cannot be deleted.");db.Entry(g).Property(z=>z.ConcurrencyVersion).OriginalValue=version;g.SoftDelete(stamp);await Save(db,ct);}

    public async Task<IReadOnlyList<InvoiceDto>> InvoicesAsync(long? contractId,CancellationToken ct){await using ContractsDbContext db=await factory.CreateDbContextAsync(ct);List<InvoiceDto> rows=await InvoiceQuery(db,contractId).ToListAsync(ct);return rows.OrderByDescending(x=>x.Date).ThenByDescending(x=>x.Id).ToList();}
    public async Task<InvoiceDto> CreateInvoiceAsync(InvoiceInput x,AuditStamp stamp,CancellationToken ct){await using ContractsDbContext db=await factory.CreateDbContextAsync(ct);await EnsureContract(db,x.ContractId,ct);Invoice i=new(x.ContractId,x.Number,x.Date,x.TypeId,x.PaymentStatusId,x.AmountRial,x.VatAmountRial,x.DueDate,x.Description,stamp);db.Invoices.Add(i);await Save(db,ct);return await InvoiceById(i.Id,ct);}
    public async Task<InvoiceDto> UpdateInvoiceAsync(InvoiceUpdate x,AuditStamp stamp,CancellationToken ct){await using ContractsDbContext db=await factory.CreateDbContextAsync(ct);Invoice i=await db.Invoices.SingleOrDefaultAsync(z=>z.Id==x.Id&&!z.IsDeleted,ct)??throw new KeyNotFoundException();if(i.ContractId!=x.Values.ContractId)throw new ArgumentException("Invoice contract cannot change.");db.Entry(i).Property(z=>z.ConcurrencyVersion).OriginalValue=x.ConcurrencyVersion;InvoiceInput v=x.Values;i.Update(v.Number,v.Date,v.TypeId,v.PaymentStatusId,v.AmountRial,v.VatAmountRial,v.DueDate,v.Description,stamp);await Save(db,ct);return await InvoiceById(i.Id,ct);}
    public async Task DeleteInvoiceAsync(long id,long version,AuditStamp stamp,CancellationToken ct){await using ContractsDbContext db=await factory.CreateDbContextAsync(ct);Invoice i=await db.Invoices.SingleOrDefaultAsync(z=>z.Id==id&&!z.IsDeleted,ct)??throw new KeyNotFoundException();db.Entry(i).Property(z=>z.ConcurrencyVersion).OriginalValue=version;i.SoftDelete(stamp);await Save(db,ct);}

    public async Task<IReadOnlyList<DocumentDto>> DocumentsAsync(long? contractId,CancellationToken ct){await using ContractsDbContext db=await factory.CreateDbContextAsync(ct);List<DocumentProjection> rows=await DocumentQuery(db,contractId).OrderByDescending(x=>x.UploadedAt).ToListAsync(ct);return rows.Select(DocumentDto).ToList();}
    public async Task<DocumentDto> UploadDocumentAsync(DocumentUploadInput x,AuditStamp stamp,CancellationToken ct){PreparedDocument p=await PrepareFile(x.ContractId,x.SourcePath,ct);try{await using ContractsDbContext db=await factory.CreateDbContextAsync(ct);await EnsureContract(db,x.ContractId,ct);if(!await db.Set<DocumentType>().AnyAsync(z=>z.Id==x.DocumentTypeId&&z.IsActive,ct))throw new ArgumentException("Document type is invalid.");Publish(p);ContractDocument d=new(x.ContractId,x.DocumentTypeId,p.OriginalName,p.StoredName,p.RelativePath,p.Size,p.Hash,stamp);db.ContractDocuments.Add(d);try{await Save(db,ct);}catch{DeleteIfExists(p.FinalPath);throw;}return await DocumentById(d.Id,ct);}catch{DeleteIfExists(p.TempPath);throw;}}
    public async Task<DocumentDto> ReplaceDocumentAsync(DocumentReplaceInput x,AuditStamp stamp,CancellationToken ct){PreparedDocument p=await PrepareFile(0,x.SourcePath,ct);string? oldPath=null;try{await using ContractsDbContext db=await factory.CreateDbContextAsync(ct);ContractDocument d=await db.ContractDocuments.SingleOrDefaultAsync(z=>z.Id==x.Id,ct)??throw new KeyNotFoundException();if(!await db.Set<DocumentType>().AnyAsync(z=>z.Id==x.DocumentTypeId&&z.IsActive,ct))throw new ArgumentException("Document type is invalid.");p=RelocatePrepared(p,d.ContractId,ct);oldPath=Resolve(d.RelativePath);db.Entry(d).Property(z=>z.ConcurrencyVersion).OriginalValue=x.ConcurrencyVersion;Publish(p);d.Replace(x.DocumentTypeId,p.OriginalName,p.StoredName,p.RelativePath,p.Size,p.Hash,stamp);try{await Save(db,ct);}catch{DeleteIfExists(p.FinalPath);throw;}if(!StringComparer.OrdinalIgnoreCase.Equals(oldPath,p.FinalPath))DeleteIfExists(oldPath);return await DocumentById(d.Id,ct);}catch{DeleteIfExists(p.TempPath);throw;}}
    public async Task DeleteDocumentAsync(long id,long version,AuditStamp stamp,CancellationToken ct){await using ContractsDbContext db=await factory.CreateDbContextAsync(ct);ContractDocument d=await db.ContractDocuments.SingleOrDefaultAsync(z=>z.Id==id,ct)??throw new KeyNotFoundException();string path=Resolve(d.RelativePath);db.Entry(d).Property(z=>z.ConcurrencyVersion).OriginalValue=version;db.ContractDocuments.Remove(d);await Save(db,ct);DeleteIfExists(path);}

    public async Task<IReadOnlyList<AlertDto>> AlertsAsync(long? contractId,CancellationToken ct){await using ContractsDbContext db=await factory.CreateDbContextAsync(ct);List<AlertDto> rows=await AlertQuery(db,contractId).ToListAsync(ct);return rows.OrderBy(x=>x.DueDate).ThenBy(x=>x.Id).ToList();}
    public async Task<AlertGenerationResult> GenerateAlertsAsync(DateOnly today,AlertRuleOptions options,AuditStamp stamp,CancellationToken ct)
    {ValidateOptions(options);await using ContractsDbContext db=await factory.CreateDbContextAsync(ct);await using IDbContextTransaction tx=await db.Database.BeginTransactionAsync(IsolationLevel.Serializable,ct);List<AlertCandidate> candidates=[];
        candidates.AddRange(await (from c in db.Contracts where !c.IsDeleted let ext=db.ContractAmendments.Where(a=>a.ContractId==c.Id&&!a.IsDeleted).Sum(a=>(int?)a.TimeExtensionDays)??0 let due=c.EndDate.AddDays(ext) where due<=today.AddDays(options.ContractWarningDays) select new AlertCandidate($"CONTRACT_EXPIRY:{c.Id}",c.Id,null,null,1,2,$"Contract {c.ContractNo} expiry",due)).ToListAsync(ct));
        candidates.AddRange(await (from g in db.Guarantees where !g.IsDeleted&&g.GuaranteeStatusId==1&&g.ExpiryDate<=today.AddDays(options.GuaranteeWarningDays) join c in db.Contracts on g.ContractId equals c.Id select new AlertCandidate($"GUARANTEE_EXPIRY:{g.Id}",g.ContractId,g.Id,null,2,2,$"Guarantee {g.GuaranteeNo} expiry",g.ExpiryDate)).ToListAsync(ct));
        DateOnly financialCutoff=today.AddDays(-options.FinancialWarningDays);List<FinancialAlertProjection> finance=await (from f in db.FinancialTransactions where !f.IsDeleted&&f.DueDate<financialCutoff let allocated=f.TransactionTypeId==1?db.ReceiptAllocations.Where(a=>a.FinancialTransactionId==f.Id&&!a.Receipt!.IsDeleted).Sum(a=>(long?)a.AmountRial)??0:db.PaymentAllocations.Where(a=>a.FinancialTransactionId==f.Id&&!a.Payment!.IsDeleted).Sum(a=>(long?)a.AmountRial)??0 where f.AmountRial-allocated>0 select new FinancialAlertProjection{Id=f.Id,ContractId=f.ContractId,TypeId=f.TransactionTypeId,No=f.TransactionNo,Due=f.DueDate}).ToListAsync(ct);
        candidates.AddRange(finance.Select(f=>new AlertCandidate($"FINANCIAL_OVERDUE:{f.Id}",f.ContractId,null,f.Id,f.TypeId==1?4:3,3,$"Financial obligation {f.No} overdue",f.Due)));
        int created=0,reopened=0,refreshed=0,resolved=0;HashSet<string> keys=candidates.Select(x=>x.Key).ToHashSet(StringComparer.OrdinalIgnoreCase);
        foreach(AlertCandidate c in candidates){Alert? a=await db.Alerts.SingleOrDefaultAsync(z=>z.DeduplicationKey==c.Key&&!z.IsDeleted,ct);if(a is null){db.Alerts.Add(new(c.ContractId,c.GuaranteeId,c.FinancialId,c.TypeId,1,c.PriorityId,c.Title,c.Key,c.Due,stamp));created++;}else if(a.AlertStatusId!=1){a.Reopen(c.Due,c.Title,stamp);reopened++;}else if(a.DueDate!=c.Due||a.Title!=c.Title||a.PriorityId!=c.PriorityId){a.RefreshOpen(c.Due,c.Title,c.PriorityId,stamp);refreshed++;}}
        List<Alert> obsolete=await db.Alerts.Where(a=>!a.IsDeleted&&a.AlertStatusId==1&&(a.DeduplicationKey.StartsWith("CONTRACT_EXPIRY:")||a.DeduplicationKey.StartsWith("GUARANTEE_EXPIRY:")||a.DeduplicationKey.StartsWith("FINANCIAL_OVERDUE:"))).ToListAsync(ct);foreach(Alert a in obsolete.Where(a=>!keys.Contains(a.DeduplicationKey))){a.Resolve(stamp);resolved++;}
        await Save(db,ct);await tx.CommitAsync(ct);return new(created,reopened,refreshed,resolved);}
    public async Task ResolveAlertAsync(long id,long version,AuditStamp stamp,CancellationToken ct){await using ContractsDbContext db=await factory.CreateDbContextAsync(ct);Alert a=await db.Alerts.SingleOrDefaultAsync(z=>z.Id==id&&!z.IsDeleted,ct)??throw new KeyNotFoundException();db.Entry(a).Property(z=>z.ConcurrencyVersion).OriginalValue=version;a.Resolve(stamp);await Save(db,ct);}
    public async Task ReopenAlertAsync(long id,long version,AuditStamp stamp,CancellationToken ct){await using ContractsDbContext db=await factory.CreateDbContextAsync(ct);Alert a=await db.Alerts.SingleOrDefaultAsync(z=>z.Id==id&&!z.IsDeleted,ct)??throw new KeyNotFoundException();db.Entry(a).Property(z=>z.ConcurrencyVersion).OriginalValue=version;a.Reopen(a.DueDate,a.Title,stamp);await Save(db,ct);}

    public async Task<IReadOnlyList<EvaluationDto>> EvaluationsAsync(long? contractId,CancellationToken ct){await using ContractsDbContext db=await factory.CreateDbContextAsync(ct);List<EvaluationDto> rows=await EvaluationQuery(db,contractId).ToListAsync(ct);return rows.OrderByDescending(x=>x.Date).ThenByDescending(x=>x.Id).ToList();}
    public async Task<EvaluationDto> CreateEvaluationAsync(EvaluationInput x,AuditStamp stamp,CancellationToken ct){await using ContractsDbContext db=await factory.CreateDbContextAsync(ct);Contract c=await db.Contracts.SingleOrDefaultAsync(z=>z.Id==x.ContractId&&!z.IsDeleted,ct)??throw new KeyNotFoundException();ContractorEvaluation e=new(x.ContractId,c.PartyId,x.Date,x.QualityScore,x.TimeScore,x.FinancialScore,x.HseScore,x.Notes,stamp);db.ContractorEvaluations.Add(e);await Save(db,ct);return await EvaluationById(e.Id,ct);}
    public async Task<EvaluationDto> UpdateEvaluationAsync(EvaluationUpdate x,AuditStamp stamp,CancellationToken ct){await using ContractsDbContext db=await factory.CreateDbContextAsync(ct);ContractorEvaluation e=await db.ContractorEvaluations.SingleOrDefaultAsync(z=>z.Id==x.Id&&!z.IsDeleted,ct)??throw new KeyNotFoundException();if(e.ContractId!=x.Values.ContractId)throw new ArgumentException("Evaluation contract cannot change.");db.Entry(e).Property(z=>z.ConcurrencyVersion).OriginalValue=x.ConcurrencyVersion;EvaluationInput v=x.Values;e.Update(v.Date,v.QualityScore,v.TimeScore,v.FinancialScore,v.HseScore,v.Notes,stamp);await Save(db,ct);return await EvaluationById(e.Id,ct);}
    public async Task DeleteEvaluationAsync(long id,long version,AuditStamp stamp,CancellationToken ct){await using ContractsDbContext db=await factory.CreateDbContextAsync(ct);ContractorEvaluation e=await db.ContractorEvaluations.SingleOrDefaultAsync(z=>z.Id==id&&!z.IsDeleted,ct)??throw new KeyNotFoundException();db.Entry(e).Property(z=>z.ConcurrencyVersion).OriginalValue=version;e.SoftDelete(stamp);await Save(db,ct);}

    // Query builders intentionally remain instance members so this repository has one consistent extension seam.
#pragma warning disable CA1822
    private IQueryable<AmendmentDto> AmendmentQuery(ContractsDbContext db,long? cid)=>from a in db.ContractAmendments.AsNoTracking() where !a.IsDeleted&&(!cid.HasValue||a.ContractId==cid) join c in db.Contracts on a.ContractId equals c.Id let total=db.ContractAmendments.Where(x=>x.ContractId==c.Id&&!x.IsDeleted).Sum(x=>(long?)x.AmountChangeRial)??0 let ext=db.ContractAmendments.Where(x=>x.ContractId==c.Id&&!x.IsDeleted).Sum(x=>(int?)x.TimeExtensionDays)??0 select new AmendmentDto(a.Id,a.ConcurrencyVersion,a.ContractId,c.ContractNo,a.AmendmentNo,a.AmendmentDate,a.Subject,a.AmountChangeRial,a.TimeExtensionDays,a.Description,a.AttachmentPath,c.BaseAmountRial+total,c.EndDate,c.EndDate.AddDays(ext));
    private async Task<AmendmentDto> AmendmentById(long id,CancellationToken ct){await using ContractsDbContext db=await factory.CreateDbContextAsync(ct);List<AmendmentDto> rows=await AmendmentQuery(db,null).ToListAsync(ct);return rows.Single(x=>x.Id==id);}
    private IQueryable<GuaranteeProjection> GuaranteeQuery(ContractsDbContext db,long? cid)=>from g in db.Guarantees.AsNoTracking() where !g.IsDeleted&&(!cid.HasValue||g.ContractId==cid) join c in db.Contracts on g.ContractId equals c.Id join t in db.Set<GuaranteeType>() on g.GuaranteeTypeId equals t.Id join s in db.Set<GuaranteeStatus>() on g.GuaranteeStatusId equals s.Id join b0 in db.Set<Bank>() on g.BankId equals b0.Id into banks from b in banks.DefaultIfEmpty() select new GuaranteeProjection{Id=g.Id,Version=g.ConcurrencyVersion,ContractId=g.ContractId,ContractNo=c.ContractNo,TypeId=g.GuaranteeTypeId,Type=t.TitleFa,Number=g.GuaranteeNo,BankId=g.BankId,Bank=b==null?null:b.TitleFa,Issue=g.IssueDate,Expiry=g.ExpiryDate,Amount=g.AmountRial,StatusId=g.GuaranteeStatusId,Status=s.TitleFa,Description=g.Description};
    private static GuaranteeDto GuaranteeDto(GuaranteeProjection x,DateOnly today){long effective=GuaranteeLifecyclePolicy.EffectiveStatus(x.StatusId,x.Expiry,today);return new(x.Id,x.Version,x.ContractId,x.ContractNo,x.TypeId,x.Type,x.Number,x.BankId,x.Bank,x.Issue,x.Expiry,x.Amount,effective,effective==3&&x.StatusId==1?"منقضی":x.Status,x.Expiry<today,x.Description);}
    private async Task<GuaranteeDto> GuaranteeById(long id,DateOnly today,CancellationToken ct){await using ContractsDbContext db=await factory.CreateDbContextAsync(ct);GuaranteeProjection x=await GuaranteeQuery(db,null).SingleAsync(z=>z.Id==id,ct);return GuaranteeDto(x,today);}
    private IQueryable<InvoiceDto> InvoiceQuery(ContractsDbContext db,long? cid)=>from i in db.Invoices.AsNoTracking() where !i.IsDeleted&&(!cid.HasValue||i.ContractId==cid) join c in db.Contracts on i.ContractId equals c.Id join t in db.Set<InvoiceType>() on i.InvoiceTypeId equals t.Id join s in db.Set<PaymentStatus>() on i.PaymentStatusId equals s.Id select new InvoiceDto(i.Id,i.ConcurrencyVersion,i.ContractId,c.ContractNo,i.InvoiceNo,i.InvoiceDate,i.InvoiceTypeId,t.TitleFa,i.AmountRial,i.VatAmountRial,i.AmountRial+i.VatAmountRial,i.DueDate,i.PaymentStatusId,s.TitleFa,i.Description);
    private async Task<InvoiceDto> InvoiceById(long id,CancellationToken ct){await using ContractsDbContext db=await factory.CreateDbContextAsync(ct);List<InvoiceDto> rows=await InvoiceQuery(db,null).ToListAsync(ct);return rows.Single(x=>x.Id==id);}
    private IQueryable<DocumentProjection> DocumentQuery(ContractsDbContext db,long? cid)=>from d in db.ContractDocuments.AsNoTracking() where !cid.HasValue||d.ContractId==cid join c in db.Contracts on d.ContractId equals c.Id join t in db.Set<DocumentType>() on d.DocumentTypeId equals t.Id join u in db.Users on d.CreatedByUserId equals u.Id select new DocumentProjection{Id=d.Id,Version=d.ConcurrencyVersion,ContractId=d.ContractId,ContractNo=c.ContractNo,TypeId=d.DocumentTypeId,Type=t.TitleFa,Original=d.OriginalFileName,Stored=d.StoredFileName,Relative=d.RelativePath,Size=d.FileSize,Hash=d.ContentHashSha256,UploadedAt=d.CreatedAtUtc,UploadedBy=d.CreatedByUserId!.Value,Uploader=u.DisplayName};
    private DocumentDto DocumentDto(DocumentProjection x)=>new(x.Id,x.Version,x.ContractId,x.ContractNo,x.TypeId,x.Type,x.Original,x.Stored,x.Relative,x.Size,x.Hash,x.UploadedAt,x.UploadedBy,x.Uploader,!File.Exists(Resolve(x.Relative)));
    private async Task<DocumentDto> DocumentById(long id,CancellationToken ct){await using ContractsDbContext db=await factory.CreateDbContextAsync(ct);return DocumentDto(await DocumentQuery(db,null).SingleAsync(x=>x.Id==id,ct));}
    private IQueryable<AlertDto> AlertQuery(ContractsDbContext db,long? cid)=>from a in db.Alerts.AsNoTracking() where !a.IsDeleted&&(!cid.HasValue||a.ContractId==cid) join c in db.Contracts on a.ContractId equals c.Id join t in db.Set<AlertType>() on a.AlertTypeId equals t.Id join s in db.Set<AlertStatus>() on a.AlertStatusId equals s.Id join p in db.Set<Priority>() on a.PriorityId equals p.Id select new AlertDto(a.Id,a.ConcurrencyVersion,a.ContractId,c.ContractNo,t.TitleFa,s.TitleFa,p.TitleFa,a.Title,a.DueDate,a.DeduplicationKey);
    private IQueryable<EvaluationDto> EvaluationQuery(ContractsDbContext db,long? cid)=>from e in db.ContractorEvaluations.AsNoTracking() where !e.IsDeleted&&(!cid.HasValue||e.ContractId==cid) join c in db.Contracts on e.ContractId equals c.Id join p in db.Parties on e.PartyId equals p.Id select new EvaluationDto(e.Id,e.ConcurrencyVersion,e.ContractId,c.ContractNo,e.PartyId,p.Name,e.EvaluationDate,e.QualityScore,e.TimeScore,e.FinancialScore,e.HseScore,Math.Round((e.QualityScore+e.TimeScore+e.FinancialScore+e.HseScore)/4m,1,MidpointRounding.AwayFromZero),e.Notes);
    private async Task<EvaluationDto> EvaluationById(long id,CancellationToken ct){await using ContractsDbContext db=await factory.CreateDbContextAsync(ct);List<EvaluationDto> rows=await EvaluationQuery(db,null).ToListAsync(ct);return rows.Single(x=>x.Id==id);}
    private static Task<List<SimpleLookupDto>> Refs<T>(ContractsDbContext db,CancellationToken ct)where T:ReferenceEntity=>db.Set<T>().AsNoTracking().Where(x=>x.IsActive).OrderBy(x=>x.SortOrder).Select(x=>new SimpleLookupDto(x.Id,x.Code,x.TitleFa,x.SortOrder)).ToListAsync(ct);
    private static async Task EnsureContract(ContractsDbContext db,long id,CancellationToken ct){if(!await db.Contracts.AnyAsync(x=>x.Id==id&&!x.IsDeleted,ct))throw new KeyNotFoundException("Contract was not found.");}
    private static string? SafeOptionalRelative(string? value){if(string.IsNullOrWhiteSpace(value))return null;string p=value.Replace('\\','/');if(Path.IsPathRooted(value)||p.Contains(':',StringComparison.Ordinal)||p.Split('/').Any(x=>x is "." or ".."))throw new ArgumentException("Attachment path must be relative.");return p;}
    private async Task<PreparedDocument> PrepareFile(long contractId,string source,CancellationToken ct){string full=Path.GetFullPath(source);if(!File.Exists(full))throw new FileNotFoundException("Document source file was not found.",full);FileInfo info=new(full);if(info.Length<=0||info.Length>storage.MaxFileSizeBytes)throw new InvalidOperationException("Document size is outside policy.");string ext=Path.GetExtension(info.Name).ToLowerInvariant();if(!storage.AllowedExtensions.Contains(ext))throw new InvalidOperationException("Document type is not allowed.");Directory.CreateDirectory(Root());string staging=Path.Combine(Root(),".staging");Directory.CreateDirectory(staging);string token=Guid.NewGuid().ToString("N");string temp=Path.Combine(staging,token+".tmp");await using(FileStream input=File.OpenRead(full))await using(FileStream output=new(temp,FileMode.CreateNew,FileAccess.Write,FileShare.None,81920,true)){await input.CopyToAsync(output,ct);}string hash;await using(FileStream hashStream=File.OpenRead(temp)){hash=Convert.ToHexString(await SHA256.HashDataAsync(hashStream,ct));}string stored=token+ext;string relative=$"contracts/{contractId}/{stored}";string final=Resolve(relative);return new(info.Name,stored,relative,info.Length,hash,temp,final);}
    private PreparedDocument RelocatePrepared(PreparedDocument p,long contractId,CancellationToken ct){if(p.RelativePath.StartsWith($"contracts/{contractId}/",StringComparison.Ordinal))return p;string relative=$"contracts/{contractId}/{p.StoredName}";ct.ThrowIfCancellationRequested();return p with{RelativePath=relative,FinalPath=Resolve(relative)};}
    private void Publish(PreparedDocument p){Directory.CreateDirectory(Path.GetDirectoryName(p.FinalPath)!);File.Move(p.TempPath,p.FinalPath,false);}
#pragma warning restore CA1822
    private string Root()=>Path.GetFullPath(storage.RootPath);private string Resolve(string relative){string root=Root();string full=Path.GetFullPath(relative.Replace('/',Path.DirectorySeparatorChar),root);string prefix=root.TrimEnd(Path.DirectorySeparatorChar)+Path.DirectorySeparatorChar;if(!full.StartsWith(prefix,StringComparison.OrdinalIgnoreCase))throw new InvalidOperationException("Document path escapes storage root.");return full;}
    private static void DeleteIfExists(string? path){if(!string.IsNullOrWhiteSpace(path)&&File.Exists(path))File.Delete(path);}
    private static void ValidateOptions(AlertRuleOptions o){if(o.ContractWarningDays is<0 or>3650||o.GuaranteeWarningDays is<0 or>3650||o.FinancialWarningDays is<0 or>3650)throw new ArgumentOutOfRangeException(nameof(o));}
    private static async Task Save(ContractsDbContext db,CancellationToken ct){try{await db.SaveChangesAsync(ct);}catch(DbUpdateConcurrencyException){throw new MasterDataConflictException("Record changed; reload and retry.");}catch(DbUpdateException e)when(e.InnerException is SqliteException s&&s.SqliteErrorCode==19){throw new MasterDataDuplicateException("Duplicate number/key or invalid dependency.");}}
    private sealed record PreparedDocument(string OriginalName,string StoredName,string RelativePath,long Size,string Hash,string TempPath,string FinalPath);
    private sealed record AlertCandidate(string Key,long ContractId,long? GuaranteeId,long? FinancialId,long TypeId,long PriorityId,string Title,DateOnly Due);
    private sealed class FinancialAlertProjection{public long Id{get;init;}public long ContractId{get;init;}public long TypeId{get;init;}public string No{get;init;}="";public DateOnly Due{get;init;}}
    private sealed class GuaranteeProjection{public long Id{get;init;}public long Version{get;init;}public long ContractId{get;init;}public string ContractNo{get;init;}="";public long TypeId{get;init;}public string Type{get;init;}="";public string Number{get;init;}="";public long? BankId{get;init;}public string? Bank{get;init;}public DateOnly Issue{get;init;}public DateOnly Expiry{get;init;}public long Amount{get;init;}public long StatusId{get;init;}public string Status{get;init;}="";public string? Description{get;init;}}
    private sealed class DocumentProjection{public long Id{get;init;}public long Version{get;init;}public long ContractId{get;init;}public string ContractNo{get;init;}="";public long TypeId{get;init;}public string Type{get;init;}="";public string Original{get;init;}="";public string Stored{get;init;}="";public string Relative{get;init;}="";public long Size{get;init;}public string? Hash{get;init;}public DateTimeOffset UploadedAt{get;init;}public long UploadedBy{get;init;}public string Uploader{get;init;}="";}
